function MillstoneCraneHookMaker.completeMaking(m) local q=1.0+(MillstoneCraneHookMaker.getQualityBonus()/100); if MillstoneCraneHookMaker.maker then q=q+(MillstoneCraneHookMaker.maker.skill/140) end; q=math.min(2.5,q); MillstoneCraneHookMaker.productStock[m.productType]=(MillstoneCraneHookMaker.productStock[m.productType] or 0)+m.quantity; MillstoneCraneHookMaker.totalProducts=MillstoneCraneHookMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillstoneCraneHookMaker.maker then MillstoneCraneHookMaker.maker.itemsMade=MillstoneCraneHookMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillstoneCraneHookMaker.maker.skill=math.min(100,MillstoneCraneHookMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kljuka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millstonecranehook.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillstoneCraneHookMaker.update(dt) if not _G.state then return end; MillstoneCraneHookMaker.dayTimer=MillstoneCraneHookMaker.dayTimer+dt; if MillstoneCraneHookMaker.dayTimer>=30 then MillstoneCraneHookMaker.dayTimer=0; for i=#MillstoneCraneHookMaker.activeMaking,1,-1 do local m=MillstoneCraneHookMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillstoneCraneHookMaker.completeMaking(m); table.remove(MillstoneCraneHookMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillstoneCraneHookMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillstoneCraneHookMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
